import React, { useState } from "react";

export default function ContactPage() {
  const [formData, setFormData] = useState({
    fullName: "",
    email: "",
    message: ""
  });

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = () => {
    if (!formData.fullName || !formData.email || !formData.message) {
      alert("Please fill in all fields");
      return;
    }
    
    console.log("Form submitted:", formData);
    alert("Message sent successfully!");
    setFormData({ fullName: "", email: "", message: "" });
  };

  return (
    <section className="min-h-screen mt-12 relative">
      <div className="absolute inset-0 z-0">
        <div className="w-full h-full bg-gradient-to-br from-blue-900 via-purple-900 to-indigo-900"></div>
        <div className="absolute inset-0 bg-black/60"></div>
      </div>
      
      <div className="relative z-10 flex flex-col min-h-screen">
        <div className="container flex flex-col flex-1 px-6 py-12 mx-auto">
          <div className="flex-1 lg:flex lg:items-center lg:-mx-6">
            <div className="text-white lg:w-1/2 lg:mx-6">
              <h1 className="text-3xl font-semibold capitalize">
                Empowering IT with AI-Driven Innovation
              </h1>
              <p className="max-w-xl mt-6">
                At{" "}
                <span className="font-semibold text-green-400">
                  Data Panther
                </span>
                , we help IT companies unlock business potential with advanced
                analytics, AI solutions, and intelligent automation.
              </p>
              <button className="px-8 py-3 mt-6 text-sm font-medium tracking-wide text-white bg-blue-600 rounded-md hover:bg-blue-500 focus:outline-none transition-colors duration-200">
                Get in Touch
              </button>

              <div className="mt-8">
                <h3 className="text-sm uppercase text-gray-300 tracking-wide">
                  Follow us
                </h3>
                <div className="flex mt-4 gap-6">
                  <a
                    href="https://linkedin.com/company/data-panther"
                    className="text-white hover:text-green-400 transition-colors duration-200"
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      fill="currentColor"
                      viewBox="0 0 24 24"
                      className="w-6 h-6"
                    >
                      <path d="M4.98 3.5a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5ZM3 8.98h4v12H3zM9.5 8.98h3.8v1.64h.05c.53-.99 1.84-2.04 3.78-2.04 4.05 0 4.8 2.67 4.8 6.13V21h-4v-5.2c0-1.24-.03-2.84-1.73-2.84-1.74 0-2 1.36-2 2.75V21h-4z" />
                    </svg>
                  </a>

                  <a
                    href="mailto:info@datapanther.com"
                    className="text-white hover:text-green-400 transition-colors duration-200"
                  >
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      fill="currentColor"
                      viewBox="0 0 24 24"
                      className="w-6 h-6"
                    >
                      <path d="M20 4H4a2 2 0 0 0-2 2v12c0 1.103.897 2 2 2h16a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2Zm0 2v.511l-8 5.333-8-5.333V6h16ZM4 18V8.489l8 5.333 8-5.333V18H4Z" />
                    </svg>
                  </a>

                  <a
                    href="tel:+1234567890"
                    className="text-white hover:text-green-400 transition-colors duration-200"
                  >
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      fill="currentColor"
                      viewBox="0 0 24 24"
                      className="w-6 h-6"
                    >
                      <path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z"/>
                    </svg>
                  </a>
                </div>
              </div>
            </div>

            <div className="mt-10 lg:w-1/2 lg:mx-6">
              <div className="w-full px-8 py-10 bg-white rounded-xl shadow-2xl dark:bg-gray-900 lg:max-w-xl">
                <h2 className="text-xl font-medium text-gray-700 dark:text-white">
                  Contact Form
                </h2>
                <p className="mt-2 text-gray-500 dark:text-gray-300">
                  Ask us anything. We would love to hear from you.
                </p>

                <div className="mt-6 space-y-6">
                  <div>
                    <label className="block text-sm text-gray-600 dark:text-white">
                      Full Name
                    </label>
                    <input
                      type="text"
                      name="fullName"
                      value={formData.fullName}
                      onChange={handleInputChange}
                      placeholder="John Doe"
                      className="w-full px-4 py-2 mt-1 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300 dark:bg-gray-800 dark:text-white dark:border-gray-600"
                    />
                  </div>
                  <div>
                    <label className="block text-sm text-gray-600 dark:text-white">
                      Email
                    </label>
                    <input
                      type="email"
                      name="email"
                      value={formData.email}
                      onChange={handleInputChange}
                      placeholder="john@example.com"
                      className="w-full px-4 py-2 mt-1 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300 dark:bg-gray-800 dark:text-white dark:border-gray-600"
                    />
                  </div>
                  <div>
                    <label className="block text-sm text-gray-600 dark:text-white">
                      Message
                    </label>
                    <textarea
                      name="message"
                      value={formData.message}
                      onChange={handleInputChange}
                      rows="4"
                      placeholder="Write your message..."
                      className="w-full px-4 py-2 mt-1 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300 dark:bg-gray-800 dark:text-white dark:border-gray-600 resize-vertical"
                    />
                  </div>
                  <button
                    onClick={handleSubmit}
                    className="w-full px-4 py-2 text-white bg-blue-600 rounded-md hover:bg-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-300 transition-colors duration-200"
                  >
                    Send Message
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}